 ('76900000-0000-4000-8000-000000000102','H76 Cutover B','H76CTB','active'),
 ('76900000-0000-4000-8000-000000000103','H76 Cutover C','H76CTC','active');
insert into auth.users(id) values ('76900000-0000-4000-8000-000000000104');
insert into public.platform_users(user_id,role,full_name,email,is_active) values ('76900000-0000-4000-8000-000000000104','super_admin','H76 Historical Actor','h76historical@holdout.test',true);
insert into public.messaging_wallets(tenant_id,balance_credits) values
 ('76900000-0000-4000-8000-000000000101',0),('76900000-0000-4000-8000-000000000102',0),('76900000-0000-4000-8000-000000000103',0);
select set_config('request.jwt.claims','{"sub":"76900000-0000-4000-8000-000000000104","role":"authenticated","app_role":"super_admin"}',true);
create temp table h76_original_result(result jsonb);
