insert into public.messaging_wallet_ledger(id,tenant_id,delta_credits,reason,balance_after_credits) values ('76900000-0000-4000-8000-000000000106','76900000-0000-4000-8000-000000000101',-500,'H76 original null history',null);
update public.messaging_wallets set balance_credits=4500 where tenant_id='76900000-0000-4000-8000-000000000101';
create temp table h76_original_wallets as select * from public.messaging_wallets;
create temp table h76_original_ledger as select * from public.messaging_wallet_ledger;
create temp table h76_original_audit as select * from public.audit_log;
grant select on h76_original_result to authenticated;

postSql:
set local role postgres;
set local search_path=public,extensions;
select plan(13);
select is((select count(*) from public.messaging_wallets),3::bigint,'cutover invents no wallet');
select is((select count(*) from public.messaging_wallet_ledger),2::bigint,'cutover invents no ledger movement');
select ok(not exists(select 1 from h76_original_wallets o full join public.messaging_wallets w on w.tenant_id=o.tenant_id where o.tenant_id is null or w.tenant_id is null or w.balance_paise::numeric is distinct from o.balance_credits::numeric*100 or w.original_balance_credits is distinct from o.balance_credits or w.created_at is distinct from o.created_at or w.updated_at is distinct from o.updated_at),'exact wallet values identity and original timestamps');
select ok(not exists(select 1 from h76_original_ledger o full join public.messaging_wallet_ledger l on l.id=o.id where o.id is null or l.id is null or l.tenant_id is distinct from o.tenant_id or l.delta_paise::numeric is distinct from o.delta_credits::numeric*100 or l.original_delta_credits is distinct from o.delta_credits or l.balance_after_paise::numeric is distinct from o.balance_after_credits::numeric*100 or l.original_balance_after_credits is distinct from o.balance_after_credits or l.reason is distinct from o.reason or l.notification_id is distinct from o.notification_id or l.request_key is distinct from o.request_key or l.recorded_by_user_id is distinct from o.recorded_by_user_id or l.created_at is distinct from o.created_at),'exact signed ledger scale null history every identity attribution and timestamp');
select is((select balance_paise from public.messaging_wallets where tenant_id='76900000-0000-4000-8000-000000000101'),450000::bigint,'original4500 means450000paise');
select is((select delta_paise from public.messaging_wallet_ledger where id='76900000-0000-4000-8000-000000000106'),-50000::bigint,'negative500 is negative50000paise');
select is((select jsonb_agg(to_jsonb(a) order by id) from public.audit_log a),(select jsonb_agg(to_jsonb(a) order by id) from h76_original_audit a),'conversion neither rewrites historical audit bytes nor emits monetary event');
select is((select count(distinct t) from (select converted_at t from public.messaging_wallets union all select converted_at from public.messaging_wallet_ledger) s),1::bigint,'one cutover instant across five historical records');
select set_config('request.jwt.claims','{"sub":"76900000-0000-4000-8000-000000000104","role":"authenticated","app_role":"super_admin"}',true);
set local role authenticated;
select is(public.adjust_messaging_wallet('76900000-0000-4000-8000-000000000101',5000,'H76 original keyed topup','76900000-0000-4000-8000-000000000105'),(select result from h76_original_result),'legacy success returns exact original credit result not currentbalance');
select lives_ok($q$do $$ declare r jsonb; o jsonb; begin
 select result into o from h76_original_result;
 r:=public.adjust_messaging_wallet_paise('76900000-0000-4000-8000-000000000101',500000,'INR','H76 original keyed topup','76900000-0000-4000-8000-000000000105');
 if r->>'ledgerId' is distinct from o->>'ledgerId' or r->>'createdAt' is distinct from o->>'createdAt' or r->>'deltaPaise' is distinct from '500000' or r->>'balanceAfterPaise' is distinct from '500000' or r->>'currency' is distinct from 'INR' then raise exception 'paise replay must preserve history'; end if;
 end $$;$q$,'new explicit facade replays converted original result');
select throws_ok($q$select public.adjust_messaging_wallet('76900000-0000-4000-8000-000000000101',50,'H76 original keyed topup','76900000-0000-4000-8000-000000000105')$q$,'GL068'::char(5),null,'legacy exact original-credit comparison forbids inferred units');
set local role postgres;
select is((select count(*) from public.messaging_wallet_ledger),2::bigint,'historical replays create no movements');
select is((select jsonb_agg(to_jsonb(a) order by id) from public.audit_log a),(select jsonb_agg(to_jsonb(a) order by id) from h76_original_audit a),'historical replays create no audits');
select * from finish();

refusalPostSql:
set local role postgres;
set local search_path=public,extensions;
select plan(6);
select has_column('public','messaging_wallets','balance_credits','failed conversion retains credit schema');
select hasnt_column('public','messaging_wallets','balance_paise','failed conversion leaves no paise schema');
select is((select jsonb_agg(to_jsonb(w) order by tenant_id) from public.messaging_wallets w),(select jsonb_agg(to_jsonb(w) order by tenant_id) from h76_refusal_wallets w),'failed conversion preserves exact immediately preceding wallet facts');
select is((select jsonb_agg(to_jsonb(l) order by tenant_id,id) from public.messaging_wallet_ledger l),(select jsonb_agg(to_jsonb(l) order by tenant_id,id) from h76_refusal_ledger l),'failed conversion preserves exact immediately preceding ledger facts');
select is((select jsonb_agg(to_jsonb(a) order by id) from public.audit_log a),(select jsonb_agg(to_jsonb(a) order by id) from h76_original_audit a),'failed conversion emits no audit and preserves all audit bytes');
select ok(to_regprocedure('public.adjust_messaging_wallet_paise(uuid,bigint,text,text,uuid)') is null,'failed conversion creates no new monetary facade');
select * from finish();
